      if(!pipeline_ready()&&staff_can('staff.manage',$user)):?><section class="workspace-card"><h2>Enable stage history</h2><p>Transitions between stages are already rule-checked. Enabling history adds an append-only, attributed record of every stage move on each inquiry.</p><form method="post"><?php admin_action('pipeline_setup');admin_input('owner_password','Your current owner password','','password','required autocomplete="current-password"');admin_check('confirm','I want every pipeline stage move recorded with actor and time.',false);?><button class="btn gold">Enable stage history</button></form></section><?php endif;
